import { sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  boolean,
  char,
  check,
  date,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

import {
  BUCKET_STATUSES,
  LOCATION_PRIVACY,
  PLACE_TYPES,
  PUBLICATION_STATUSES,
} from "@/types/domain";

/**
 * Database schema (PostgreSQL). Conventions:
 *  - UUID primary keys (spec requirement; tables stay small so v4 index locality is a non-issue).
 *  - timestamptz everywhere, defaults generated by the database, never the client.
 *  - Every foreign key is indexed. Hot read paths use partial indexes.
 *  - Soft delete via `deleted_at` for places; public queries always filter on it.
 *  - Coordinates are numeric(9,6) (~0.1 m) with range checks. A PostGIS upgrade path is
 *    documented in docs/database.md (generated geography column + GiST index).
 *  - Row Level Security is enabled on every table with no policies (see migration
 *    `0001_security_and_triggers.sql`): the server connects with a privileged role, while any
 *    auto-generated Data API (e.g. Supabase PostgREST) is denied by default.
 */

export const placeTypeEnum = pgEnum("place_type", PLACE_TYPES);
export const publicationStatusEnum = pgEnum("publication_status", PUBLICATION_STATUSES);
export const bucketStatusEnum = pgEnum("bucket_status", BUCKET_STATUSES);
export const locationPrivacyEnum = pgEnum("location_privacy", LOCATION_PRIVACY);

// Must be inlined (not a bind parameter) because it ends up inside a CHECK constraint.
const SLUG_PATTERN = sql.raw("'^[a-z0-9]+(-[a-z0-9]+)*$'");

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

const coordinates = {
  lat: numeric("lat", { precision: 9, scale: 6, mode: "number" }).notNull(),
  lng: numeric("lng", { precision: 9, scale: 6, mode: "number" }).notNull(),
};

/** A multi-stop journey. Used to group the timeline and draw dashed route lines. */
export const trips = pgTable(
  "trips",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull(),
    title: text("title").notNull(),
    startDate: date("start_date", { mode: "string" }),
    endDate: date("end_date", { mode: "string" }),
    description: text("description").notNull().default(""),
    status: publicationStatusEnum("status").notNull().default("draft"),
    isDemo: boolean("is_demo").notNull().default(false),
    ...timestamps,
  },
  (table) => [
    uniqueIndex("trips_slug_key").on(table.slug),
    check("trips_slug_format", sql`${table.slug} ~ ${SLUG_PATTERN}`),
    check(
      "trips_dates_ordered",
      sql`${table.startDate} is null or ${table.endDate} is null or ${table.endDate} >= ${table.startDate}`,
    ),
  ],
);

export const places = pgTable(
  "places",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull(),
    title: text("title").notNull(),
    type: placeTypeEnum("type").notNull().default("other"),
    ...coordinates,
    locationPrivacy: locationPrivacyEnum("location_privacy").notNull().default("exact"),

    // Geocoder provenance: where these coordinates came from.
    geocoderProvider: text("geocoder_provider"),
    providerPlaceId: text("provider_place_id"),
    placeName: text("place_name"),
    formattedAddress: text("formatted_address"),
    city: text("city"),
    region: text("region"),
    countryCode: char("country_code", { length: 2 }),
    countryName: text("country_name"),

    visitedAt: date("visited_at", { mode: "string" }),
    excerpt: text("excerpt").notNull().default(""),
    story: text("story").notNull().default(""),
    funnyMoment: text("funny_moment"),
    rating: smallint("rating"),

    status: publicationStatusEnum("status").notNull().default("draft"),
    coverPhotoId: uuid("cover_photo_id").references((): AnyPgColumn => photos.id, {
      onDelete: "set null",
    }),
    tripId: uuid("trip_id").references(() => trips.id, { onDelete: "set null" }),

    /** True for synthetic sample content. Always labelled "demo" in the UI. */
    isDemo: boolean("is_demo").notNull().default(false),

    ...timestamps,
    publishedAt: timestamp("published_at", { withTimezone: true }),
    deletedAt: timestamp("deleted_at", { withTimezone: true }),
  },
  (table) => [
    uniqueIndex("places_slug_key").on(table.slug),
    // Hot path: public map, timeline and passport read published, non-deleted rows.
    index("places_public_idx")
      .on(table.visitedAt.desc(), table.publishedAt)
      .where(sql`${table.status} = 'published' and ${table.deletedAt} is null`),
    index("places_trip_id_idx").on(table.tripId),
    index("places_cover_photo_id_idx").on(table.coverPhotoId),
    index("places_country_code_idx").on(table.countryCode),
    index("places_updated_at_idx").on(table.updatedAt.desc()),
    check("places_slug_format", sql`${table.slug} ~ ${SLUG_PATTERN}`),
    check("places_lat_range", sql`${table.lat} between -90 and 90`),
    check("places_lng_range", sql`${table.lng} between -180 and 180`),
    check("places_rating_range", sql`${table.rating} is null or ${table.rating} between 1 and 5`),
    check(
      "places_country_code_format",
      sql`${table.countryCode} is null or ${table.countryCode} ~ '^[A-Z]{2}$'`,
    ),
    check("places_title_length", sql`char_length(${table.title}) between 1 and 140`),
    // A published place must carry the moment it went (or will go) live.
    check(
      "places_published_has_timestamp",
      sql`${table.status} <> 'published' or ${table.publishedAt} is not null`,
    ),
  ],
);

/** Photos live in object storage; the database stores keys and metadata only. */
export const photos = pgTable(
  "photos",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** Null while the photo sits in the media library, not yet attached to a place. */
    placeId: uuid("place_id").references(() => places.id, { onDelete: "set null" }),
    /** Key of the full-size processed image. Variants are derived (see features/uploads/keys.ts). */
    storageKey: text("storage_key").notNull(),
    alt: text("alt").notNull().default(""),
    caption: text("caption"),
    width: integer("width").notNull(),
    height: integer("height").notNull(),
    bytes: integer("bytes").notNull().default(0),
    sortOrder: integer("sort_order").notNull().default(0),
    /** Tiny base64 placeholder for next/image `blurDataURL`. */
    blurDataUrl: text("blur_data_url"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("photos_storage_key_key").on(table.storageKey),
    index("photos_place_sort_idx").on(table.placeId, table.sortOrder),
    check("photos_dimensions_positive", sql`${table.width} > 0 and ${table.height} > 0`),
  ],
);

export const tags = pgTable(
  "tags",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    slug: text("slug").notNull(),
    name: text("name").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("tags_slug_key").on(table.slug),
    check("tags_slug_format", sql`${table.slug} ~ ${SLUG_PATTERN}`),
  ],
);

export const placeTags = pgTable(
  "place_tags",
  {
    placeId: uuid("place_id")
      .notNull()
      .references(() => places.id, { onDelete: "cascade" }),
    tagId: uuid("tag_id")
      .notNull()
      .references(() => tags.id, { onDelete: "cascade" }),
  },
  (table) => [
    primaryKey({ columns: [table.placeId, table.tagId] }),
    index("place_tags_tag_id_idx").on(table.tagId),
  ],
);

/** Planned destinations. Completing one does not count as a visit unless a published place exists. */
export const bucketListItems = pgTable(
  "bucket_list_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    placeName: text("place_name").notNull(),
    ...coordinates,
    countryCode: char("country_code", { length: 2 }),
    countryName: text("country_name"),
    geocoderProvider: text("geocoder_provider"),
    providerPlaceId: text("provider_place_id"),
    note: text("note").notNull().default(""),
    status: bucketStatusEnum("status").notNull().default("planned"),
    linkedPlaceId: uuid("linked_place_id").references(() => places.id, { onDelete: "set null" }),
    isDemo: boolean("is_demo").notNull().default(false),
    ...timestamps,
  },
  (table) => [
    index("bucket_list_items_linked_place_id_idx").on(table.linkedPlaceId),
    index("bucket_list_items_status_idx").on(table.status),
    check("bucket_lat_range", sql`${table.lat} between -90 and 90`),
    check("bucket_lng_range", sql`${table.lng} between -180 and 180`),
    check(
      "bucket_country_code_format",
      sql`${table.countryCode} is null or ${table.countryCode} ~ '^[A-Z]{2}$'`,
    ),
  ],
);

/** Tiny key/value store for one-off flags (e.g. "demo content was seeded once"). */
export const siteSettings = pgTable("site_settings", {
  key: text("key").primaryKey(),
  value: text("value").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export type PlaceRow = typeof places.$inferSelect;
export type NewPlaceRow = typeof places.$inferInsert;
export type PhotoRow = typeof photos.$inferSelect;
export type NewPhotoRow = typeof photos.$inferInsert;
export type TripRow = typeof trips.$inferSelect;
export type NewTripRow = typeof trips.$inferInsert;
export type TagRow = typeof tags.$inferSelect;
export type BucketListItemRow = typeof bucketListItems.$inferSelect;
export type NewBucketListItemRow = typeof bucketListItems.$inferInsert;
